/* Vereinheitlicht alles, was hereinkommt, auf EIN Format.
   Egal ob Website-Formular, Portal-Mail, Terminklick oder Tageslauf. */
const raus = [];

for (const item of $input.all()) {
  const j = item.json || {};
  let e;

  const istWebhook = (j.query !== undefined) || (j.body !== undefined) || (j.headers !== undefined);
  const istMail    = (j.textPlain !== undefined) || (j.textHtml !== undefined) || (j.from !== undefined);

  if (istWebhook) {
    const q = j.query || {};
    const b = j.body  || {};

    if (q.lead || q.t) {
      /* Der Interessent hat auf einen Terminvorschlag geklickt. */
      e = { quelle: 'termin', leadId: String(q.lead || ''), slot: String(q.t || '') };
    } else {
      /* Anfrage über das Website-Formular. */
      const txt = b.nachricht || b.message || b.text || b.anfrage || '';
      e = {
        quelle:  'anfrage',
        kanal:   'Website-Formular',
        name:    String(b.name || b.Name || '').trim(),
        email:   String(b.email || b.Email || b.mail || b['e-mail'] || '').trim(),
        telefon: String(b.telefon || b.phone || b.tel || '').trim(),
        betreff: String(b.betreff || b.subject || 'Anfrage über die Website').trim(),
        text:    String(txt).trim()
      };
    }
  } else if (istMail) {
    /* Anfrage per E-Mail (Portal-Weiterleitung, direkte Mail). */
    const von = String(j.from || '');
    const tref = von.match(/<([^>]+)>/);
    const klartext = j.textPlain || j.text ||
                     String(j.textHtml || '').replace(/<style[\s\S]*?<\/style>/gi, ' ')
                                             .replace(/<[^>]+>/g, ' ');
    e = {
      quelle:  'anfrage',
      kanal:   'E-Mail / Portal',
      name:    String(von.split('<')[0] || '').replace(/["']/g, '').trim(),
      email:   String(tref ? tref[1] : von).trim(),
      telefon: '',
      betreff: String(j.subject || 'Anfrage per E-Mail').trim(),
      text:    String(klartext).replace(/\s+\n/g, '\n').replace(/[ \t]{2,}/g, ' ').trim()
    };
  } else {
    /* Zeitplan: der tägliche Lauf. */
    e = { quelle: 'tageslauf' };
  }

  e.empfangen = new Date().toISOString();
  raus.push({ json: e });
}

return raus;

/* ═══════════════════════════════════════════════════════════
   HIER UND NUR HIER WIRD PRO AUTOHAUS ANGEPASST.
   Alle anderen Nodes lesen ihre Werte aus diesem Block.
   ═══════════════════════════════════════════════════════════ */
const CFG = {

  /* ---- Autohaus ------------------------------------------ */
  autohaus:       'Autohaus Muster GmbH',
  ort:            'Musterstadt',
  telefon:        '0123 456789',
  webseite:       'https://www.autohaus-muster.de',
  absenderName:   'Autohaus Muster GmbH',
  absenderEmail:  'info@autohaus-muster.de',

  /* ---- Google Sheet (ID aus der Tabellen-URL) ------------- */
  sheetId:        'HIER_DIE_GOOGLE_SHEET_ID_EINTRAGEN',
  blattLeads:     'Leads',
  blattFahrzeuge: 'Fahrzeuge',

  /* ---- Kalender ------------------------------------------ */
  kalenderId:     'primary',

  /* ---- Verkäufer (wird der Reihe nach zugeteilt) ---------- */
  verkaeufer: [
    { name: 'Max Mustermann',  email: 'max@autohaus-muster.de',  marken: ['BMW', 'MINI'] },
    { name: 'Anna Beispiel',   email: 'anna@autohaus-muster.de', marken: ['VW', 'Audi', 'Skoda'] }
  ],
  verkaufsleitung: 'leitung@autohaus-muster.de',

  /* ---- Basis-Adresse dieser n8n-Instanz ------------------- */
  /* Ohne Schrägstrich am Ende. Der Termin-Link hängt daran.  */
  webhookBasis:   'https://DEINE-N8N-ADRESSE/webhook',
  pfadTermin:     'autohaus-termin',

  /* ---- Probefahrt-Zeiten --------------------------------- */
  terminZeiten:   ['10:00', '14:00', '16:30'],
  terminDauerMin: 45,
  vorlaufTage:    1,      /* frühester Termin: morgen */

  /* ---- Nachfassen ---------------------------------------- */
  nachfassTage:   [2, 5, 10],
  archivNachTagen: 45,
  erinnerungStundenVorher: 24,

  /* ---- KI ------------------------------------------------- */
  modell:         'claude-opus-5',
  tonfall:        'freundlich, sachlich, ohne Werbefloskeln, Sie-Form',

  /* ---- Tagesbericht -------------------------------------- */
  berichtSenden:  true
};

return $input.all().map(i => ({ json: { ...i.json, cfg: CFG } }));

/* Ist das eine Antwort eines Interessenten, den wir schon kennen?
   Dann muss die Nachfass-Kette sofort stoppen. */
const a      = $('EINSTELLUNGEN').first().json;
const zeilen = $input.all().map(i => i.json).filter(r => r && r.Email);

const email   = String(a.email || '').toLowerCase().trim();
const treffer = email ? zeilen.filter(r => String(r.Email).toLowerCase().trim() === email) : [];

const offeneStati = ['neu', 'kontaktiert', 'nachgefasst', 'termin'];
const offen = treffer.filter(r => offeneStati.includes(String(r.Status || '').toLowerCase()));

/* Der jüngste offene Vorgang gewinnt. */
offen.sort((x, y) => String(y.Eingang || '').localeCompare(String(x.Eingang || '')));

return [{
  json: {
    ...a,
    istAntwort:     offen.length > 0,
    bekannterLead:  offen[0] || null,
    frueherAnfragen: treffer.length
  }
}];

/* Der Kunde hat geantwortet: Kette stoppen, Verkäufer sofort informieren. */
const d   = $json;
const cfg = d.cfg;
const l   = d.bekannterLead || {};
const jetzt = new Date().toISOString();

const verkEmail = l.VerkaeuferEmail || (cfg.verkaeufer[0] && cfg.verkaeufer[0].email) || cfg.verkaufsleitung;

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#1a2430;line-height:1.6">
  <p style="margin:0 0 14px"><b>${d.name || d.email} hat geantwortet.</b> Die Nachfass-Kette wurde gestoppt.</p>
  <table cellpadding="6" style="border-collapse:collapse;font-size:14px">
    <tr><td style="color:#5b6b80">Fahrzeug</td><td><b>${l.Fahrzeug || 'unbekannt'}</b></td></tr>
    <tr><td style="color:#5b6b80">Kaufabsicht</td><td>${l.Kaufabsicht || '—'}</td></tr>
    <tr><td style="color:#5b6b80">E-Mail</td><td>${d.email}</td></tr>
    <tr><td style="color:#5b6b80">Telefon</td><td>${l.Telefon || d.telefon || '—'}</td></tr>
    <tr><td style="color:#5b6b80">Erste Anfrage</td><td>${(l.Eingang || '').substring(0, 10) || '—'}</td></tr>
  </table>
  <p style="margin:16px 0 6px;color:#5b6b80">Neue Nachricht:</p>
  <div style="background:#f5f7fa;border-left:3px solid #2f6da8;padding:12px 14px;white-space:pre-wrap">${String(d.text || '').substring(0, 2000)}</div>
  <p style="margin:18px 0 0;color:#5b6b80;font-size:13px">Bitte persönlich übernehmen — das System fasst hier nicht weiter nach.</p>
</div>`;

return [{
  json: {
    /* Spalten für die Tabelle */
    LeadID:         l.LeadID || '',
    Status:         'geantwortet',
    Sequenz:        'gestoppt',
    LetzterKontakt: jetzt,
    NaechsterSchritt: 'Persönlich melden',
    Notiz:          String(d.text || '').substring(0, 500),
    /* Felder für die Mail */
    mailAn:      verkEmail,
    mailBetreff: `Kunde hat geantwortet: ${d.name || d.email}`,
    mailHtml:    html,
    cfg:         cfg
  }
}];

/* Baut die vollständige Anfrage an die Claude-API.
   Alles wird hier zusammengesetzt, damit der HTTP-Node nur noch sendet. */
const d   = $('Antwort oder neue Anfrage?').first().json;
const cfg = d.cfg;

/* --- Fahrzeugbestand aus der Tabelle (nur verfügbare) ---- */
const bestand = $input.all()
  .map(i => i.json)
  .filter(r => r && r.FahrzeugID && String(r.Status || 'verfuegbar').toLowerCase() !== 'verkauft')
  .slice(0, 120)
  .map(r => ({
    id:        String(r.FahrzeugID),
    fahrzeug:  [r.Marke, r.Modell, r.Variante].filter(Boolean).join(' '),
    ez:        r.Erstzulassung || '',
    km:        r.Kilometer || '',
    kraftstoff: r.Kraftstoff || '',
    getriebe:  r.Getriebe || '',
    leistung:  r.Leistung || '',
    preis:     r.Preis || '',
    farbe:     r.Farbe || ''
  }));

/* --- Drei konkrete Probefahrt-Termine vorschlagen -------- */
function werktagPlus(startTage) {
  const d0 = new Date();
  d0.setHours(0, 0, 0, 0);
  let n = 0, tage = 0;
  while (n < startTage) {
    tage++;
    d0.setDate(d0.getDate() + 1);
    const w = d0.getDay();
    if (w !== 0 && w !== 6) n++;
  }
  return d0;
}
const slots = [];
for (let k = 0; k < cfg.terminZeiten.length; k++) {
  const tag = werktagPlus(cfg.vorlaufTage + k);
  const [hh, mm] = String(cfg.terminZeiten[k]).split(':');
  tag.setHours(parseInt(hh, 10), parseInt(mm || '0', 10), 0, 0);
  const iso = tag.getFullYear() + '-' +
              String(tag.getMonth() + 1).padStart(2, '0') + '-' +
              String(tag.getDate()).padStart(2, '0') + 'T' +
              String(tag.getHours()).padStart(2, '0') + ':' +
              String(tag.getMinutes()).padStart(2, '0');
  const wochentage = ['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'];
  slots.push({
    iso: iso,
    text: wochentage[tag.getDay()] + ', ' + String(tag.getDate()).padStart(2,'0') + '.' +
          String(tag.getMonth()+1).padStart(2,'0') + '. um ' + cfg.terminZeiten[k] + ' Uhr'
  });
}

/* --- Der Auftrag an die KI -------------------------------- */
const system = [
  'Du bist die Anfragen-Annahme von ' + cfg.autohaus + ' in ' + cfg.ort + '.',
  'Du liest eine eingehende Kundenanfrage und tust zwei Dinge:',
  '1. Du erkennst, worum es geht: gewünschtes Fahrzeug, Kaufabsicht, mögliche Inzahlungnahme, Dringlichkeit.',
  '2. Du schreibst die Antwort an den Interessenten.',
  '',
  'Regeln für die Antwort:',
  '- Sprache: Deutsch, Sie-Form. Tonfall: ' + cfg.tonfall + '.',
  '- Nimm direkten Bezug auf das genannte Fahrzeug und auf die gestellten Fragen.',
  '- Erfinde niemals Ausstattung, Preise, Kilometerstände oder Zusagen. Nutze nur den Bestand unten.',
  '- Ist das Fahrzeug nicht im Bestand, sage das offen und nenne hoechstens zwei passende Alternativen daraus.',
  '- Wird eine Inzahlungnahme erwaehnt: bestaetige, dass eine Bewertung moeglich ist, ohne eine Summe zu nennen.',
  '- Schliesse mit dem Angebot einer Probefahrt. Die konkreten Termine haengt das System an, nenne selbst keine.',
  '- Keine Anrede-Floskeln wie "vielen Dank fuer Ihr Interesse an unserem Hause". Komm zur Sache.',
  '- Laenge: 90 bis 160 Woerter. Absaetze mit Leerzeile trennen. Keine Grussformel und keine Signatur, die haengt das System an.',
  '',
  'Bewertung (Feld score, 0 bis 100): hohe Kaufabsicht, konkretes Fahrzeug, kurzer Zeitrahmen und Inzahlungnahme erhoehen den Wert.'
].join('\n');

const nutzer = [
  '# Eingegangene Anfrage',
  'Kanal: '   + d.kanal,
  'Name: '    + (d.name || 'nicht angegeben'),
  'E-Mail: '  + d.email,
  'Telefon: ' + (d.telefon || 'nicht angegeben'),
  'Betreff: ' + d.betreff,
  '',
  'Nachricht:',
  String(d.text || '').substring(0, 6000),
  '',
  '# Verfuegbarer Fahrzeugbestand',
  bestand.length ? JSON.stringify(bestand) : '(Bestandsliste ist leer)',
  '',
  '# Frueherer Kontakt',
  d.frueherAnfragen > 0 ? ('Dieser Interessent hat bereits ' + d.frueherAnfragen + ' Mal angefragt.')
                        : 'Keine frueheren Anfragen bekannt.'
].join('\n');

const schema = {
  type: 'object',
  properties: {
    kunde_name:            { type: 'string', description: 'Name des Interessenten, leer wenn unbekannt' },
    fahrzeug_wunsch:       { type: 'string', description: 'Gewuenschtes Fahrzeug in Worten' },
    fahrzeug_id:           { type: 'string', description: 'Passende FahrzeugID aus dem Bestand, sonst leer' },
    kaufabsicht:           { type: 'string', enum: ['hoch', 'mittel', 'niedrig', 'unklar'] },
    inzahlungnahme:        { type: 'boolean' },
    inzahlung_fahrzeug:    { type: 'string', description: 'Das angebotene Fahrzeug, sonst leer' },
    dringlichkeit:         { type: 'string', enum: ['sofort', 'wochen', 'monate', 'unklar'] },
    probefahrt_gewuenscht: { type: 'boolean' },
    finanzierung_thema:    { type: 'boolean' },
    score:                 { type: 'integer', description: 'Potenzial von 0 bis 100' },
    zusammenfassung:       { type: 'string', description: 'Ein Satz fuer den Verkaeufer' },
    antwort_betreff:       { type: 'string' },
    antwort_text:          { type: 'string', description: 'Reiner Text, Absaetze durch Leerzeile getrennt' }
  },
  required: ['kunde_name','fahrzeug_wunsch','fahrzeug_id','kaufabsicht','inzahlungnahme',
             'inzahlung_fahrzeug','dringlichkeit','probefahrt_gewuenscht','finanzierung_thema',
             'score','zusammenfassung','antwort_betreff','antwort_text'],
  additionalProperties: false
};

const apiBody = {
  model: cfg.modell,
  max_tokens: 2000,
  thinking: { type: 'disabled' },
  output_config: { effort: 'low', format: { type: 'json_schema', schema: schema } },
  system: system,
  messages: [{ role: 'user', content: nutzer }]
};

return [{ json: { ...d, bestand: bestand, slots: slots, apiBody: apiBody } }];

/* Liest die KI-Antwort, faellt bei Problemen sauber zurueck
   und baut daraus CRM-Zeile, Kundenmail und Verkaeufermail. */
const vor   = $('KI-Auftrag bauen').first().json;
const cfg   = vor.cfg;
const roh   = $json;

/* --- Antwort der API auslesen ---------------------------- */
let a = {};
let kiOk = false;
try {
  const block = (roh.content || []).find(b => b && b.type === 'text');
  if (block && block.text) { a = JSON.parse(block.text); kiOk = true; }
} catch (e) { kiOk = false; }

/* --- Rueckfallebene, falls die KI nicht erreichbar war ---- */
if (!kiOk) {
  a = {
    kunde_name: vor.name, fahrzeug_wunsch: '', fahrzeug_id: '',
    kaufabsicht: 'unklar', inzahlungnahme: false, inzahlung_fahrzeug: '',
    dringlichkeit: 'unklar', probefahrt_gewuenscht: false, finanzierung_thema: false,
    score: 40,
    zusammenfassung: 'Automatische Auswertung war nicht moeglich, bitte manuell pruefen.',
    antwort_betreff: 'Ihre Anfrage bei ' + cfg.autohaus,
    antwort_text: 'vielen Dank fuer Ihre Nachricht. Wir haben Ihre Anfrage erhalten und melden uns '
                + 'schnellstmoeglich persoenlich bei Ihnen.'
  };
}

/* --- Verkaeufer zuordnen: erst nach Marke, sonst reihum --- */
const wunsch = String(a.fahrzeug_wunsch || '').toLowerCase();
let verk = cfg.verkaeufer.find(v => (v.marken || []).some(m => wunsch.includes(String(m).toLowerCase())));
if (!verk) {
  const idx = Math.abs(String(vor.email || '').split('').reduce((s, c) => s + c.charCodeAt(0), 0)) % cfg.verkaeufer.length;
  verk = cfg.verkaeufer[idx];
}

/* --- Lead-Nummer ----------------------------------------- */
const jetzt   = new Date();
const leadId  = 'L-' + jetzt.getFullYear() + String(jetzt.getMonth()+1).padStart(2,'0') +
                String(jetzt.getDate()).padStart(2,'0') + '-' +
                Math.random().toString(36).substring(2, 7).toUpperCase();

/* --- Terminlinks ----------------------------------------- */
const basis = cfg.webhookBasis.replace(/\/+$/, '') + '/' + cfg.pfadTermin;
const linkListe = vor.slots.map(s =>
  `<tr><td style="padding:5px 0">
     <a href="${basis}?lead=${encodeURIComponent(leadId)}&t=${encodeURIComponent(s.iso)}"
        style="display:inline-block;padding:10px 18px;background:#2f6da8;color:#ffffff;
               text-decoration:none;border-radius:8px;font-size:14px">${s.text}</a>
   </td></tr>`).join('');

/* --- Kundenmail ------------------------------------------ */
const absaetze = String(a.antwort_text || '').split(/\n\s*\n/)
  .map(p => `<p style="margin:0 0 14px">${p.replace(/\n/g, '<br>')}</p>`).join('');

const anrede = a.kunde_name && a.kunde_name.trim()
  ? 'Guten Tag ' + a.kunde_name.trim() + ','
  : 'Guten Tag,';

const kundenHtml = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#1a2430;line-height:1.65;max-width:620px">
  <p style="margin:0 0 14px">${anrede}</p>
  ${absaetze}
  <p style="margin:22px 0 10px"><b>Probefahrt — waehlen Sie einfach einen Termin:</b></p>
  <table cellpadding="0" cellspacing="0">${linkListe}</table>
  <p style="margin:16px 0 0;font-size:13px;color:#5b6b80">
    Passt keiner der Termine? Antworten Sie einfach auf diese E-Mail.
  </p>
  <hr style="border:none;border-top:1px solid #e3e8ef;margin:26px 0 14px">
  <p style="margin:0;font-size:13px;color:#5b6b80">
    ${cfg.autohaus} · ${cfg.ort}<br>
    Telefon ${cfg.telefon} · <a href="${cfg.webseite}" style="color:#2f6da8">${cfg.webseite}</a><br>
    Ihr Ansprechpartner: ${verk.name}
  </p>
</div>`;

/* --- Verkaeufermail -------------------------------------- */
const ampel = a.score >= 70 ? '#2e8b6b' : (a.score >= 40 ? '#b5883e' : '#8a94a0');
const verkHtml = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#1a2430;line-height:1.6;max-width:620px">
  <p style="margin:0 0 6px;font-size:13px;color:#5b6b80">Neue Anfrage · ${vor.kanal}</p>
  <p style="margin:0 0 16px;font-size:19px"><b>${a.fahrzeug_wunsch || 'Fahrzeug unklar'}</b>
     <span style="background:${ampel};color:#fff;border-radius:20px;padding:3px 11px;font-size:13px;margin-left:8px">
       Potenzial ${a.score}</span></p>
  <p style="margin:0 0 16px">${a.zusammenfassung}</p>
  <table cellpadding="6" style="border-collapse:collapse;font-size:14px">
    <tr><td style="color:#5b6b80">Name</td><td><b>${a.kunde_name || vor.name || '—'}</b></td></tr>
    <tr><td style="color:#5b6b80">E-Mail</td><td><a href="mailto:${vor.email}" style="color:#2f6da8">${vor.email}</a></td></tr>
    <tr><td style="color:#5b6b80">Telefon</td><td>${vor.telefon || '—'}</td></tr>
    <tr><td style="color:#5b6b80">Kaufabsicht</td><td>${a.kaufabsicht}</td></tr>
    <tr><td style="color:#5b6b80">Zeitrahmen</td><td>${a.dringlichkeit}</td></tr>
    <tr><td style="color:#5b6b80">Inzahlungnahme</td><td>${a.inzahlungnahme ? (a.inzahlung_fahrzeug || 'ja') : 'nein'}</td></tr>
    <tr><td style="color:#5b6b80">Finanzierung Thema</td><td>${a.finanzierung_thema ? 'ja' : 'nein'}</td></tr>
    <tr><td style="color:#5b6b80">Fahrzeug im Bestand</td><td>${a.fahrzeug_id || 'nicht zugeordnet'}</td></tr>
    <tr><td style="color:#5b6b80">Lead-Nummer</td><td>${leadId}</td></tr>
  </table>
  <p style="margin:18px 0 6px;color:#5b6b80">Originalnachricht:</p>
  <div style="background:#f5f7fa;border-left:3px solid #2f6da8;padding:12px 14px;white-space:pre-wrap;font-size:14px">${String(vor.text || '').substring(0, 2000)}</div>
  <p style="margin:18px 0 0;font-size:13px;color:#5b6b80">
    Der Interessent hat bereits eine Antwort mit drei Terminvorschlaegen erhalten.
    ${kiOk ? '' : '<b>Hinweis: die automatische Auswertung ist ausgefallen — bitte selbst lesen.</b>'}
  </p>
</div>`;

/* --- Eine Zeile fuer die Tabelle ------------------------- */
const zeile = {
  LeadID:             leadId,
  Eingang:            jetzt.toISOString(),
  Quelle:             vor.kanal,
  Name:               a.kunde_name || vor.name || '',
  Email:              vor.email,
  Telefon:            vor.telefon || '',
  Nachricht:          String(vor.text || '').substring(0, 900),
  Fahrzeug:           a.fahrzeug_wunsch || '',
  FahrzeugID:         a.fahrzeug_id || '',
  Kaufabsicht:        a.kaufabsicht,
  Inzahlungnahme:     a.inzahlungnahme ? 'ja' : 'nein',
  InzahlungFahrzeug:  a.inzahlung_fahrzeug || '',
  Dringlichkeit:      a.dringlichkeit,
  Score:              a.score,
  Verkaeufer:         verk.name,
  VerkaeuferEmail:    verk.email,
  Status:             'kontaktiert',
  Sequenz:            'laeuft',
  LetzterKontakt:     jetzt.toISOString(),
  NaechsterSchritt:   'Nachfassen an Tag ' + cfg.nachfassTage[0],
  Termin:             '',
  TerminBestaetigt:   'nein',
  Notiz:              a.zusammenfassung
};

return [{
  json: {
    ...zeile,
    cfg:              cfg,
    kiOk:             kiOk,
    kundeAn:          vor.email,
    kundeBetreff:     a.antwort_betreff || ('Ihre Anfrage bei ' + cfg.autohaus),
    kundeHtml:        kundenHtml,
    verkAn:           verk.email,
    verkBetreff:      '[' + a.score + '] Neue Anfrage: ' + (a.fahrzeug_wunsch || 'Fahrzeug unklar') + ' — ' + (a.kunde_name || vor.email),
    verkHtml:         verkHtml
  }
}];

/* Der tägliche Lauf: was steht heute an? */
const cfg = $('EINSTELLUNGEN').first().json.cfg;
const jetzt = new Date();
const tag = 24 * 60 * 60 * 1000;

const alle = $input.all().map(i => i.json).filter(r => r && r.LeadID && r.Email);
const aufgaben = [];

for (const l of alle) {
  const status  = String(l.Status || '').toLowerCase();
  const sequenz = String(l.Sequenz || '').toLowerCase();

  /* --- 1. Erinnerung an eine bevorstehende Probefahrt ----- */
  if (l.Termin && String(l.TerminBestaetigt).toLowerCase() === 'ja') {
    const t = new Date(l.Termin);
    if (!isNaN(t.getTime())) {
      const stundenBis = (t.getTime() - jetzt.getTime()) / 3600000;
      const schon = String(l.NaechsterSchritt || '').includes('Erinnert');
      if (stundenBis > 0 && stundenBis <= cfg.erinnerungStundenVorher && !schon) {
        aufgaben.push({ json: { typ: 'erinnerung', lead: l, cfg: cfg } });
      }
    }
    continue;   /* Wer einen Termin hat, wird nicht nachgefasst. */
  }

  /* --- 2. Kette gestoppt oder abgeschlossen? -------------- */
  if (sequenz === 'gestoppt' || ['geantwortet','verkauft','verloren','archiviert'].includes(status)) {
    /* --- 3. Archivieren nach langer Stille --------------- */
    const letzte = new Date(l.LetzterKontakt || l.Eingang || 0);
    const alterTage = (jetzt.getTime() - letzte.getTime()) / tag;
    if (status !== 'archiviert' && alterTage > cfg.archivNachTagen) {
      aufgaben.push({ json: { typ: 'archiv', lead: l, cfg: cfg } });
    }
    continue;
  }

  /* --- 4. Nachfassen an Tag 2, 5 und 10 ------------------ */
  const eingang = new Date(l.Eingang || 0);
  if (isNaN(eingang.getTime())) continue;
  const alter = Math.floor((jetzt.getTime() - eingang.getTime()) / tag);

  const bereits = (String(l.NaechsterSchritt || '').match(/Nachgefasst an Tag (\d+)/g) || [])
                    .map(s => parseInt(s.replace(/\D/g, ''), 10));
  const hoechsteStufe = bereits.length ? Math.max(...bereits) : 0;

  const faellig = cfg.nachfassTage.filter(t => alter >= t && t > hoechsteStufe);
  if (faellig.length) {
    aufgaben.push({ json: { typ: 'nachfass', stufe: Math.max(...faellig), alter: alter, lead: l, cfg: cfg } });
    continue;
  }

  /* --- 5. Nach der letzten Stufe: archivieren ------------ */
  const letzterTag = cfg.nachfassTage[cfg.nachfassTage.length - 1];
  if (hoechsteStufe >= letzterTag && alter > cfg.archivNachTagen) {
    aufgaben.push({ json: { typ: 'archiv', lead: l, cfg: cfg } });
  }
}

/* --- 6. Tagesbericht an die Verkaufsleitung -------------- */
if (cfg.berichtSenden) {
  aufgaben.push({ json: { typ: 'bericht', alle: alle, aufgaben: aufgaben.length, cfg: cfg } });
}

return aufgaben;

