/* Tagesbericht an die Verkaufsleitung. */
const d   = $input.first().json;
const cfg = d.cfg;
const alle = d.alle || [];
const tag = 24 * 60 * 60 * 1000;
const jetzt = Date.now();

const seit = (r, t) => {
  const x = new Date(r.Eingang || 0).getTime();
  return !isNaN(x) && (jetzt - x) < t * tag;
};

const neu24     = alle.filter(r => seit(r, 1));
const neu7      = alle.filter(r => seit(r, 7));
const offen     = alle.filter(r => ['neu','kontaktiert','nachgefasst'].includes(String(r.Status||'').toLowerCase()));
const termine   = alle.filter(r => String(r.TerminBestaetigt||'').toLowerCase() === 'ja' &&
                                   new Date(r.Termin || 0).getTime() > jetzt);
const antworten = alle.filter(r => String(r.Status||'').toLowerCase() === 'geantwortet');

const heiss = offen.filter(r => Number(r.Score || 0) >= 70)
                   .sort((a, b) => Number(b.Score||0) - Number(a.Score||0))
                   .slice(0, 8);

